        return s.count('(') == s.count(')')

    def check_combinations(s1, s2):
        return is_balanced(s1 + s2) or is_balanced(s2 + s1) or is_balanced(s1 + s2 + '(') or is_balanced(s2 + s1 + '(') or is_balanced(s1 + s2 + ')') or is_balanced(s2 + s1 + ')')

    return 'Yes' if check_combinations(lst[0], lst[1]) else 'No

