    s1, s2 = lst
    open1, close1 = s1.count('('), s1.count(')')
    open2, close2 = s2.count('('), s2.count(')')
    total_open = open1 + open2
    total_close = close1 + close2
    if total_open == total_close:
        return 'Yes'
    elif total_open > total_close:
        return 'Yes' if close1 == total_open - close2 else 'No'
    else:
        return 'Yes' if open1 == total_close - open2 else 'No

