def is_sorted(lst):
    if len(lst) <= 1:
        return True
    seen = {}
    for i in range(len(lst) - 1):
        if lst[i] not in seen:
            seen[lst[i]] = 1
        else:
            return False
        if lst[i] >= lst[i + 1]:
            return False
    return True


